import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import './project-dialog.css';

import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import { delegate, signal } from 'kerfjs';
import { FileText } from 'lucide';

const records = {
  alpha: { name: 'Northstar migration', owner: 'Mara Chen', state: 'In review', updated: 'Today, 09:42' },
  beta: { name: 'Tablet navigation', owner: 'Sam Rivera', state: 'Ready', updated: 'Yesterday, 16:20' },
  gamma: { name: 'Contrast audit', owner: 'Inez Okafor', state: 'Blocked', updated: 'Monday, 11:05' },
} as const;
type RecordId = keyof typeof records;
type DialogElement = HTMLElement & { open: boolean };

export function createProjectDialog(root: HTMLElement) {
  const selected = signal<RecordId>('alpha');
  let invoker: HTMLElement | null = null;
  const render = () => <section><button class="dialog-button" data-primary="true" type="button" data-action="open-dialog">Open project details</button><wa-dialog class="project-dialog" without-header aria-labelledby="project-dialog-title" aria-describedby="project-dialog-summary"><DialogHeader title="Project details" titleId="project-dialog-title" summary="Compare delivery state without leaving the workspace." summaryId="project-dialog-summary" icon={<LucideIcon icon={FileText} name="file-text" />} actions={<wa-button appearance="plain" data-action="close-dialog">Close</wa-button>} /><div class="project-dialog__scroll kui-scroll-owner"><div class="project-master-detail kui-dialog-body"><nav class="project-master-detail__master kui-sidebar kui-pane-body" aria-label="Projects"><MenuHeader label="Recent projects" />{Object.entries(records).map(([id, record]) => <MenuItem action="select-record" itemId={id} label={record.name} selected={selected.value === id} multiline />)}</nav><section class="project-master-detail__detail kui-pane-body kui-section-stack" aria-live="polite"><h3>{records[selected.value].name}</h3><ValueTable label="Project details"><div><dt>Owner</dt><dd>{records[selected.value].owner}</dd></div><div><dt>Status</dt><dd>{records[selected.value].state}</dd></div><div><dt>Updated</dt><dd>{records[selected.value].updated}</dd></div></ValueTable><div class="kui-control-cluster"><wa-button appearance="outlined" data-action="archive-record">Archive</wa-button><wa-button variant="brand" appearance="accent" data-action="open-record">Open project</wa-button></div></section></div></div></wa-dialog></section>;
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => {
    const dialog = root.querySelector<DialogElement>('wa-dialog');
    if (!dialog) return;
    if (element.dataset.action === 'open-dialog') { invoker = element; dialog.open = true; }
    if (element.dataset.action === 'close-dialog') dialog.open = false;
    if (element.dataset.action === 'select-record' && element.dataset.itemId in records) selected.value = element.dataset.itemId as RecordId;
  });
  const dialog = root.querySelector<DialogElement>('wa-dialog');
  const restoreFocus = () => invoker?.focus();
  dialog?.addEventListener('wa-hide', restoreFocus);
  return { render, dispose() { dispose(); dialog?.removeEventListener('wa-hide', restoreFocus); } };
}

