.project-dialog { --spacing: 0; --width: min(62rem, calc(100vw - 2rem)); }
.project-dialog__scroll { max-block-size: min(75dvh, 42rem); }
.project-master-detail { display: grid; inline-size: min(58rem, 100%); grid-template-columns: minmax(13rem, .8fr) minmax(18rem, 1.4fr); }
.project-master-detail__master { border-inline-end: 1px solid var(--kui-color-border); }
.project-master-detail__detail { min-inline-size: 0; }
.project-master-detail__detail h3 { margin: 0; }
.dialog-button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
@media (max-width: 44rem) { .project-master-detail { grid-template-columns: minmax(0, 1fr); } .project-master-detail__master { border-inline-end: 0; border-block-end: 1px solid var(--kui-color-border); } }
